INSERT INTO fc_playstyle_ids VALUES('FC27',7,'Long Ball Pass','GG Club API playerDef.playstyles(EA 실측 id) ↔ player_card_items.playstyles(기준 카드 이름) 차집합 역산 — 보유 99장 중 진화 카드를 뺀 뒤 「미해석 id 1개 ↔ 미대응 이름 1개」로 떨어진 카드 8장이 전원 Long Ball Pass를 지목 (2026-09-24 /club-sync)','HIGH(등급 C 통제 실측) — 독립 카드 8장 만장일치. 대표 사례: 린델뢰프 기준[Intercept·Jockey·Long Ball Pass] ↔ EA[12·10·7], 하우드-벨리스 기준[Aerial Fortress·Long Ball Pass·Precision Header] ↔ EA[?·7·?]. ⚠️ EA 1차 공표가 아니라 역산이다.','2026-09-24');
